package com.aiep.aihub.hr;
import static org.junit.jupiter.api.Assertions.*;
import com.aiep.aihub.api.hr.HrCandidateContracts.*;
import com.aiep.aihub.api.hr.HrPositionContracts.*;
import com.aiep.aihub.application.hr.*;
import com.aiep.aihub.domain.hr.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class HrHardActualViewTest {
 Matching view(String type,Facts facts){var fixture=new HrMatchingLifecycleTest();var old=fixture.config();var d=old.snapshot();var hard=new HardRule("hard",type,"硬条件","目标","月",BigDecimal.ONE,BigDecimal.ZERO,false,List.of("并发"),"ALL");var draft=new Draft(d.positionId(),d.name(),d.family(),d.departmentId(),d.level(),d.jdText(),d.lastStep(),d.scoring(),List.of(hard),d.criteria(),d.version());var config=new ConfigVersion("cfg","p","v1","ctx",draft,"hash","1",Instant.now());var atomic=List.of(new HrAtomicAssessment("r",HrAtomicAssessment.Level.MATCH,null,null,List.of("b")));var score=new HrScoreEngine().score(d.scoring(),new HrVerifiedFacts(List.of(new HrHardConditionEvaluator.Result("hard",HrHardConditionEvaluator.Type.valueOf(type),HrHardConditionEvaluator.Status.PASS,false,"PASS")),false),atomic,Set.of(),LocalDate.of(2026,11,11));return new HrResultAssembler().assemble("m",facts,"s",fixture.position(),config,"semantic",score,atomic);}
 Facts facts(List<StructuredFact> structured,List<Field> fields){var f=new HrMatchingLifecycleTest().facts();return new Facts(f.candidateId(),f.resumeVersionId(),f.filename(),f.pageCount(),f.qualityScore(),f.status(),f.profile(),f.blocks(),fields,f.skills(),fields.size(),fields.size(),f.version(),structured);}
 @Test void confirmed_degree_and_month_union_are_visible_while_unknown_is_null(){var education=new StructuredFact("edu","education","本科",List.of(new Evidence("b",0,4,"Java")),null,null,"本科",null,null,null,null,null);assertEquals("本科",view("EDUCATION",facts(List.of(education),List.of(new Field("edu","education","本科","CONFIRMED","",List.of("b"))))).hardConditions().getFirst().actual());assertNull(view("EDUCATION",facts(List.of(education),List.of(new Field("edu","education","本科","NEEDS_REVIEW","",List.of("b"))))).hardConditions().getFirst().actual());var work=new StructuredFact("job","employment","开发",List.of(new Evidence("b",0,4,"Java")),null,null,null,null,new DateValue("2025-01","MONTH","2025-01"),new DateValue("2025-12","MONTH","2025-12"),false,false);assertEquals("12个月",view("WORK_EXPERIENCE",facts(List.of(work),List.of(new Field("job","employment","开发","CONFIRMED","",List.of("b"))))).hardConditions().getFirst().actual());}
 @Test void semantic_actual_uses_verified_derived_hard_atom_quote(){var original=view("REQUIRED_SKILL",new HrMatchingLifecycleTest().facts());String derived=derived("hard",0);var evidence=new Evidence("b",0,4,"Java");var result=new HrResultAssembler().evidence(original,List.of(new SemanticAssessment(derived,"MATCH","",List.of(evidence))));assertEquals("Java",result.hardConditions().getFirst().actual());assertEquals(original.totalScore(),result.totalScore());var invalid=new HrResultAssembler().evidence(original,List.of(new SemanticAssessment(derived,"MATCH","",List.of(new Evidence("b",0,4,"假的")))));assertNull(invalid.hardConditions().getFirst().actual());}
 String derived(String id,int index){try{var json=com.fasterxml.jackson.databind.json.JsonMapper.builder().enable(com.fasterxml.jackson.databind.MapperFeature.SORT_PROPERTIES_ALPHABETICALLY).enable(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS).build().findAndRegisterModules();return "hard-"+HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(List.of(id,index)))).substring(0,32);}catch(Exception e){throw new RuntimeException(e);}}
}
